package com.example.starter.ride.web;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import com.example.starter.ride.ApiResult;
import com.example.starter.ride.service.RideOperationService;

/**
 * 游乐设施日检与载客联锁 API。
 */
@RestController
@RequestMapping("/api/rides")
public class RideController {

    private final RideOperationService service;

    public RideController(RideOperationService service) {
        this.service = service;
    }

    @PostMapping("/daily-check")
    public ResponseEntity<ApiResult> dailyCheck(@RequestBody com.example.starter.ride.dto.DailyCheckRequest request) {
        ApiResult result = service.dailyCheck(request);
        return ResponseEntity.status(result.httpStatus()).body(result);
    }

    @PostMapping("/trial-run")
    public ResponseEntity<ApiResult> trialRun(@RequestBody com.example.starter.ride.dto.TrialRunRequest request) {
        ApiResult result = service.trialRun(request);
        return ResponseEntity.status(result.httpStatus()).body(result);
    }

    @PostMapping("/open")
    public ResponseEntity<ApiResult> open(@RequestBody com.example.starter.ride.dto.OpenRequest request) {
        ApiResult result = service.open(request);
        return ResponseEntity.status(result.httpStatus()).body(result);
    }

    @PostMapping("/safety-fault")
    public ResponseEntity<ApiResult> safetyFault(@RequestBody com.example.starter.ride.dto.SafetyFaultRequest request) {
        ApiResult result = service.safetyFault(request);
        return ResponseEntity.status(result.httpStatus()).body(result);
    }

    @PostMapping("/readings")
    public ResponseEntity<ApiResult> reading(@RequestBody com.example.starter.ride.dto.ReadingRequest request) {
        ApiResult result = service.reading(request);
        return ResponseEntity.status(result.httpStatus()).body(result);
    }

    @PostMapping("/recheck")
    public ResponseEntity<ApiResult> recheck(@RequestBody com.example.starter.ride.dto.RecheckRequest request) {
        ApiResult result = service.recheck(request);
        return ResponseEntity.status(result.httpStatus()).body(result);
    }

    @PostMapping("/archive")
    public ResponseEntity<ApiResult> archive(@RequestBody com.example.starter.ride.dto.ArchiveRequest request) {
        ApiResult result = service.archive(request);
        return ResponseEntity.status(result.httpStatus()).body(result);
    }

    @GetMapping("/{rideId}/replay-chain")
    public ResponseEntity<ApiResult> replayChain(@PathVariable String rideId) {
        return ResponseEntity.ok(ApiResult.ok("待实现", null));
    }
}

